// NFC and NFD against Python's unicodedata, from tests/data/unicode_vectors.tsv
// (generated by tools/gen_unicode_data.py).
#include <gtest/gtest.h>

#include <cstddef>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "hebrew_normalize/hebrew_normalize.hpp"
#include "utf8.hpp"

namespace {

struct Vector {
  std::string input;
  std::string nfc;
  std::string nfd;
  std::string line;
};

std::string from_hex_list(const std::string& field) {
  std::u32string cps;
  std::istringstream words(field);
  std::string word;
  while (words >> word) {
    cps.push_back(static_cast<char32_t>(std::stoul(word, nullptr, 16)));
  }
  return hebrew_normalize::detail::encode_utf8(cps);
}

std::vector<Vector> load_vectors() {
  std::ifstream file(HN_TEST_DATA_DIR "/unicode_vectors.tsv");
  std::vector<Vector> vectors;
  std::string line;
  while (std::getline(file, line)) {
    if (line.empty() || line.front() == '#') {
      continue;
    }
    std::istringstream fields(line);
    std::string input;
    std::string nfc;
    std::string nfd;
    std::getline(fields, input, '\t');
    std::getline(fields, nfc, '\t');
    std::getline(fields, nfd, '\t');
    vectors.push_back({from_hex_list(input), from_hex_list(nfc), from_hex_list(nfd), line});
  }
  return vectors;
}

}  // namespace

TEST(UnicodeVectors, MatchPythonUnicodedata) {
  const std::vector<Vector> vectors = load_vectors();
  ASSERT_GT(vectors.size(), 500U) << "test data missing: " << HN_TEST_DATA_DIR "/unicode_vectors.tsv";
  for (const Vector& v : vectors) {
    EXPECT_EQ(hebrew_normalize::to_nfc(v.input), v.nfc) << v.line;
    EXPECT_EQ(hebrew_normalize::to_nfd(v.input), v.nfd) << v.line;
  }
}

TEST(UnicodeVectors, NormalizeIsTheSameForNfcAndNfd) {
  for (const Vector& v : load_vectors()) {
    EXPECT_EQ(hebrew_normalize::normalize(v.nfc), hebrew_normalize::normalize(v.nfd)) << v.line;
  }
}

TEST(UnicodeVersion, IsReported) { EXPECT_EQ(hebrew_normalize::unicode_version(), "16.0.0"); }
